create function public.set_project_status(p_project uuid,p_status text,p_reason text default '') returns void language plpgsql security definer set search_path='' as $$ declare old text; begin if not private.role(p_project,array['OWNER']::public.project_role[]) then raise exception 'PERMISSION_DENIED'; end if; select status into old from public.projects where id=p_project for update; if p_status='closed' then perform public.close_project(p_project,p_reason);return; end if; if p_status not in ('active','paused','closing','archived') or (p_status='archived' and old<>'closed') or (old in ('closed','archived') and p_status<>'archived') then raise exception 'INVALID_LIFECYCLE'; end if; update public.projects set status=p_status where id=p_project; perform private.log(p_project,'project_'||p_status,'projects',p_project,p_reason); end $$;
create function public.closeout_checks(p_project uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare s jsonb; checks jsonb; begin if not private.member(p_project) then raise exception 'PERMISSION_DENIED'; end if; s:=public.project_summary(p_project); checks:=jsonb_build_object('bills_settled',(s->>'bills')::bigint=0,'members_settled',(s->>'payable')::bigint=0,'advances_settled',(s->>'advances')::bigint=0,'requests_closed',not exists(select 1 from public.purchase_requests where project_id=p_project and status not in ('completed','cancelled','rejected')),'receipts_complete',not exists(select 1 from public.purchases p where p.project_id=p_project and p.status='posted' and not exists(select 1 from public.documents d where d.entity_id=p.id and d.status='ready')),'categories_complete',not exists(select 1 from public.purchases where project_id=p_project and status='posted' and category_id is null),'assets_assigned',not exists(select 1 from public.assets where project_id=p_project and status='available'),'funding_reconciled',(s->>'cash')::bigint>=0,'recoveries_settled',not exists(select 1 from public.financial_accounts where project_id=p_project and account_type='MEMBER_RECOVERY' and private.account_balance(id)<>0)); return checks; end $$;
create or replace function public.close_project(p_project uuid,p_reason text default null) returns void language plpgsql security definer set search_path='' as $$ declare s jsonb; checks jsonb; begin if not private.role(p_project,array['OWNER']::public.project_role[]) then raise exception 'PERMISSION_DENIED'; end if; perform 1 from public.projects where id=p_project for update; s:=public.project_summary(p_project); checks:=public.closeout_checks(p_project); if (s->>'payable')::bigint<>0 or (s->>'bills')::bigint<>0 or (s->>'advances')::bigint<>0 or (s->>'reserved')::bigint<>0 or not (checks->>'recoveries_settled')::boolean or exists(select 1 from public.approval_instances where project_id=p_project and status='pending') then raise exception 'UNSETTLED_PROJECT'; end if; if exists(select 1 from jsonb_each_text(checks) where value='false') and length(coalesce(p_reason,''))<5 then raise exception 'CLOSEOUT_REASON_REQUIRED'; end if; update public.projects set status='closed',closed_at=now() where id=p_project; perform private.log(p_project,'project_closed','projects',p_project,p_reason); end $$;
revoke all on function public.set_project_status(uuid,text,text),public.closeout_checks(uuid) from public;
grant execute on function public.set_project_status(uuid,text,text),public.closeout_checks(uuid) to authenticated;
